<?php
declare(strict_types=1);
$config = require __DIR__ . '/../config/database.php';
$pdo = new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$pdo->exec("UPDATE alumnos SET plan_actual_id=plan_programado_id,plan_programado_id=NULL,plan_programado_desde=NULL,updated_at=NOW() WHERE plan_programado_id IS NOT NULL AND plan_programado_desde IS NOT NULL AND plan_programado_desde<=CURDATE()");
$mesActual=(int)date('n');$anioActual=(int)date('Y');
$sql="SELECT a.id,a.nombre,a.whatsapp,a.correo,a.fecha_inicio,a.estado_administrativo,a.horario_preferido_id,a.plan_actual_id,h.hora_inicio,h.hora_fin,p.nombre plan_nombre,p.sesiones_semana,p.precio,m.estado mensualidad_estado,m.fecha_pago,
EXISTS(SELECT 1 FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO')) intensivo_activo,
(SELECT ci.id FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO') ORDER BY ci.fecha_inicio DESC LIMIT 1) intensivo_id,
(SELECT ci.fecha_inicio FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO') ORDER BY ci.fecha_inicio DESC LIMIT 1) intensivo_fecha_inicio,
(SELECT ci.fecha_fin FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO') ORDER BY ci.fecha_inicio DESC LIMIT 1) intensivo_fecha_fin,
(SELECT hi.hora_inicio FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id LEFT JOIN horarios hi ON hi.id=cia.horario_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO') ORDER BY ci.fecha_inicio DESC LIMIT 1) intensivo_hora_inicio,
(SELECT hi.hora_fin FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id LEFT JOIN horarios hi ON hi.id=cia.horario_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO') ORDER BY ci.fecha_inicio DESC LIMIT 1) intensivo_hora_fin
FROM alumnos a LEFT JOIN horarios h ON h.id=a.horario_preferido_id LEFT JOIN planes p ON p.id=a.plan_actual_id LEFT JOIN mensualidades m ON m.alumno_id=a.id AND m.mes=:mes AND m.anio=:anio ORDER BY a.nombre";
$stmt=$pdo->prepare($sql);$stmt->execute([':mes'=>$mesActual,':anio'=>$anioActual]);$alumnos=$stmt->fetchAll();
$intensivos=array_values(array_filter($alumnos,fn($a)=>(int)$a['intensivo_activo']===1));
$sinPlan=array_values(array_filter($alumnos,fn($a)=>(int)$a['intensivo_activo']!==1 && empty($a['plan_actual_id'])));
$regulares=array_values(array_filter($alumnos,fn($a)=>(int)$a['intensivo_activo']!==1 && !empty($a['plan_actual_id'])));
function e(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}function hora(string $h):string{return date('H:i',strtotime($h));}
function acceso(array $a):array{if($a['estado_administrativo']==='BAJA')return['BAJA','baja'];if($a['estado_administrativo']==='PENDIENTE')return['PENDIENTE DE PAGO','pendiente'];if((int)$a['intensivo_activo']===1)return['INTENSIVO','intensivo'];if(empty($a['plan_nombre']))return['SIN PLAN','pendiente'];if(($a['mensualidad_estado']??'')==='PAGADA')return['PUEDE TOMAR CLASE','acceso'];return['SIN DERECHO A CLASE','sin-acceso'];}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Control de Alumnos — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fa;color:#172033}.contenedor{max-width:1400px;margin:auto;padding:35px 25px}h1{margin:0 0 8px;font-size:32px}.subtitulo,.contador{color:#64748b}.subtitulo{margin-bottom:18px}.contador{margin-bottom:15px;font-size:14px}.tabs{display:flex;gap:8px;margin-bottom:16px}.tab{border:0;background:#e2e8f0;color:#334155;padding:10px 14px;border-radius:10px;font-weight:800;cursor:pointer}.tab.activa{background:#172033;color:#fff}.panel{display:none}.panel.activo{display:block}.tabla-contenedor{background:#fff;border-radius:18px;padding:16px;overflow-x:auto;box-shadow:0 4px 18px rgba(0,0,0,.06)}table{width:100%;border-collapse:collapse;min-width:900px}th{text-align:left;padding:12px;background:#f8fafc;color:#475569;font-size:12px;border-bottom:1px solid #e2e8f0}td{padding:13px 12px;border-bottom:1px solid #edf2f7;vertical-align:middle}.nombre a{font-weight:800;color:#172033;text-decoration:none}.secundario,.precio{color:#64748b;font-size:12px;margin-top:4px}.estado,.derecho{display:inline-block;padding:6px 9px;border-radius:999px;font-size:11px;font-weight:800;white-space:nowrap}.activo,.acceso{background:#dcfce7;color:#166534}.baja,.sin-acceso{background:#fee2e2;color:#991b1b}.pendiente{background:#fef3c7;color:#92400e}.intensivo{background:#dbeafe;color:#1e40af}.plan{font-weight:700}.vacio{text-align:center;padding:50px;color:#64748b}.editable{display:inline-flex;align-items:center;gap:6px}.mini-edit,.quick-pay{border:0;border-radius:7px;font-weight:800;cursor:pointer}.mini-edit{background:#eef2f7;color:#334155;width:26px;height:26px}.quick-pay{display:inline-block;margin-top:6px;padding:6px 8px;background:#dcfce7;color:#166534;font-size:11px}.mini-edit:hover{background:#e2e8f0}.sin-plan-tag{display:inline-block;padding:6px 9px;border-radius:999px;background:#fef3c7;color:#92400e;font-size:11px;font-weight:800}@media(max-width:650px){.contenedor{padding:72px 0 18px}h1,.subtitulo,.contador,.tabs{margin-left:14px;margin-right:14px}h1{font-size:25px}.subtitulo{font-size:13px}.tabs{overflow-x:auto}.tab{white-space:nowrap}.tabla-contenedor{border-radius:0;padding:0;box-shadow:none}table{min-width:720px}th{padding:10px 8px}td{padding:11px 8px;font-size:13px}.secundario,.precio{font-size:11px}.mini-edit{width:24px;height:24px}}</style></head><body><div class="contenedor"><h1>Control de Alumnos</h1><div class="subtitulo">Hache Natación — <?= sprintf('%02d/%d',$mesActual,$anioActual) ?></div><div class="contador"><?=count($regulares)?> regulares · <?=count($intensivos)?> en intensivo · <?=count($sinPlan)?> sin plan</div><div class="tabs"><button class="tab activa" data-tab="regulares">Clases regulares (<?=count($regulares)?>)</button><button class="tab" data-tab="intensivos">Cursos intensivos (<?=count($intensivos)?>)</button><button class="tab" data-tab="sin-plan">Sin plan (<?=count($sinPlan)?>)</button></div>
<div id="panel-regulares" class="panel activo"><div class="tabla-contenedor"><?php if(!$regulares):?><div class="vacio">No hay alumnos en clases regulares.</div><?php else:?><table><thead><tr><th>Alumno</th><th>WhatsApp</th><th>Horario</th><th>Plan</th><th>Estado</th><th>Acceso a clase</th></tr></thead><tbody><?php foreach($regulares as $a):$der=acceso($a);?><tr data-alumno-id="<?=e($a['id'])?>" data-estado="<?=e($a['estado_administrativo'])?>" data-mensualidad-pagada="<?=($a['mensualidad_estado']??'')==='PAGADA'?'1':'0'?>"><td><div class="nombre"><a href="ficha-alumno.php?id=<?=urlencode($a['id'])?>"><?=e($a['nombre'])?></a></div><?php if($a['correo']):?><div class="secundario"><?=e($a['correo'])?></div><?php endif;?></td><td><span class="editable"><span data-whatsapp-text><?=e($a['whatsapp'])?></span><button type="button" class="mini-edit" data-quick-edit="whatsapp" data-id="<?=e($a['id'])?>" data-value="<?=e($a['whatsapp'])?>" aria-label="Modificar WhatsApp">✎</button></span></td><td><span class="editable"><span data-horario-text><?=$a['hora_inicio']&&$a['hora_fin']?hora($a['hora_inicio']).'–'.hora($a['hora_fin']):'—'?></span><button type="button" class="mini-edit" data-quick-edit="horario" data-id="<?=e($a['id'])?>" data-value="<?=e($a['horario_preferido_id'])?>" aria-label="Modificar horario">✎</button></span></td><td><div class="plan"><?=e($a['plan_nombre'])?></div><div class="precio"><?=(int)$a['sesiones_semana']?> sesiones · $<?=number_format((float)$a['precio'],0)?></div></td><td><span class="estado <?=$a['estado_administrativo']==='ACTIVO'?'activo':($a['estado_administrativo']==='PENDIENTE'?'pendiente':'baja')?>"><?=e($a['estado_administrativo'])?></span></td><td><span class="derecho <?=$der[1]?>"><?=$der[0]?></span><?php if(($a['mensualidad_estado']??'')!=='PAGADA'&&$a['estado_administrativo']!=='BAJA'):?><div><button type="button" class="quick-pay" data-quick-pay data-id="<?=e($a['id'])?>" data-name="<?=e($a['nombre'])?>" data-price="<?=e((string)$a['precio'])?>">Pagar mes</button></div><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></div>
<div id="panel-intensivos" class="panel"><div class="tabla-contenedor"><?php if(!$intensivos):?><div class="vacio">No hay alumnos en cursos intensivos activos.</div><?php else:?><table><thead><tr><th>Alumno</th><th>WhatsApp</th><th>Horario</th><th>Curso</th><th>Estado</th></tr></thead><tbody><?php foreach($intensivos as $a):?><tr><td><div class="nombre"><a href="ficha-alumno.php?id=<?=urlencode($a['id'])?>"><?=e($a['nombre'])?></a></div><?php if($a['correo']):?><div class="secundario"><?=e($a['correo'])?></div><?php endif;?></td><td><span class="editable"><span data-whatsapp-text><?=e($a['whatsapp'])?></span><button type="button" class="mini-edit" data-quick-edit="whatsapp" data-id="<?=e($a['id'])?>" data-value="<?=e($a['whatsapp'])?>" aria-label="Modificar WhatsApp">✎</button></span></td><td><?=$a['intensivo_hora_inicio']&&$a['intensivo_hora_fin']?hora($a['intensivo_hora_inicio']).'–'.hora($a['intensivo_hora_fin']):'—'?></td><td><?php if($a['intensivo_id']):?><a href="intensivo-detalle.php?id=<?=urlencode($a['intensivo_id'])?>">Ver curso</a><div class="secundario"><?=e($a['intensivo_fecha_inicio'])?> → <?=e($a['intensivo_fecha_fin'])?></div><?php else:?>—<?php endif;?></td><td><span class="estado intensivo">INTENSIVO</span></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></div>
<div id="panel-sin-plan" class="panel"><div class="tabla-contenedor"><?php if(!$sinPlan):?><div class="vacio">No hay alumnos pendientes de asignación de plan.</div><?php else:?><table><thead><tr><th>Alumno</th><th>WhatsApp</th><th>Horario preferido</th><th>Plan</th><th>Estado</th></tr></thead><tbody><?php foreach($sinPlan as $a):?><tr><td><div class="nombre"><a href="ficha-alumno.php?id=<?=urlencode($a['id'])?>"><?=e($a['nombre'])?></a></div><?php if($a['correo']):?><div class="secundario"><?=e($a['correo'])?></div><?php endif;?></td><td><span class="editable"><span data-whatsapp-text><?=e($a['whatsapp'])?></span><button type="button" class="mini-edit" data-quick-edit="whatsapp" data-id="<?=e($a['id'])?>" data-value="<?=e($a['whatsapp'])?>" aria-label="Modificar WhatsApp">✎</button></span></td><td><span class="editable"><span data-horario-text><?=$a['hora_inicio']&&$a['hora_fin']?hora($a['hora_inicio']).'–'.hora($a['hora_fin']):'—'?></span><button type="button" class="mini-edit" data-quick-edit="horario" data-id="<?=e($a['id'])?>" data-value="<?=e($a['horario_preferido_id'])?>" aria-label="Modificar horario">✎</button></span></td><td><span class="sin-plan-tag">SIN PLAN</span></td><td><span class="estado <?=$a['estado_administrativo']==='ACTIVO'?'activo':($a['estado_administrativo']==='PENDIENTE'?'pendiente':'baja')?>"><?=e($a['estado_administrativo'])?></span></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></div></div><script>document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('activa'));document.querySelectorAll('.panel').forEach(x=>x.classList.remove('activo'));b.classList.add('activa');document.getElementById('panel-'+b.dataset.tab).classList.add('activo')}));</script><script src="/assets/alumnos-quick-edit.js" defer></script><script src="/assets/alumnos-quick-pay.js" defer></script></body></html>